"""Independent command line entry point for the Taplo-compatible CLI."""
import sys
import misc_cli


def main(argv=None):
    args = list(sys.argv[1:] if argv is None else argv)
    if misc_cli.run(args):
        return 0
    if not args:
        return 0
    command, rest = args[0], args[1:]
    aliases = {'fmt': 'format', 'check': 'lint', 'validate': 'lint', 'cfg': 'config'}
    command = aliases.get(command, command)
    if command == 'config':
        import configcmd
        return configcmd.run(rest)
    if command == 'toml-test':
        import tomltest
        return tomltest.run()
    # Command modules are contributed independently; resolve them when present.
    modules = {'format': ('formatcmd', 'run'), 'lint': ('lintcmd', 'run'),
               'get': ('getcmd', 'run'), 'completions': ('completioncmd', 'run')}
    if command in modules:
        modname, fn = modules[command]
        try:
            mod = __import__(modname)
        except ImportError:
            sys.stderr.write(f"error: {command} command unavailable\n")
            return 2
        result = getattr(mod, fn)(rest)
        return result if isinstance(result, int) else 0
    if command in ('-h', '--help', 'help'):
        sys.stdout.write(misc_cli.TOP_HELP)
        return 0
    if command in ('-V', '--version'):
        print('taplo 0.10.0')
        return 0
    sys.stderr.write(f"error: unrecognized subcommand '{command}'\n\nFor more information, try '--help'.\n")
    return 2


if __name__ == '__main__':
    raise SystemExit(main())
